"use client";

import { useRef, useState, type ComponentProps, type ReactNode } from "react";

import { IconClock } from "@rhs-ui/icons";
import { SnoozePanel } from "@rhs-ui/application/snooze-popover/panel";
import { DEFAULT_LABELS, type SnoozeLabels, type SnoozePreset, type SnoozeTime } from "@rhs-ui/application/snooze-popover/snooze";
import { Button } from "@rhs-ui/primitives/button";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";

export type { CivilDay, SnoozeLabels, SnoozePreset, SnoozeTime } from "@rhs-ui/application/snooze-popover/snooze";
export { SnoozePanel, type SnoozePanelProps } from "@rhs-ui/application/snooze-popover/panel";

export interface SnoozePopoverProps extends Omit<ComponentProps<"div">, "children" | "onChange"> {
  /**
   * The moment the person chose. It may return a promise: the row shows progress while it runs, and when it rejects the panel stays
   * open with a message so the choice can be made again. A choice that was saved closes the popover and is announced.
   */
  onSnooze: (date: Date) => void | Promise<void>;
  /** The moment every choice is worked out from, and the moment the past starts. Leave it out to use the browser's clock once the page is live; pass it for the same times in server HTML, in tests and in previews. */
  now?: SnoozeTime;
  /** The time zone the choices, the calendar and the time are read in, so the server and the browser agree. Default "UTC". */
  timeZone?: string;
  /** The language of the weekdays, the months and the way a time is written. Default "en-US". */
  locale?: string;
  /** Your own choices instead of the four defaults (later today, tomorrow morning, this weekend, next week). */
  presets?: readonly SnoozePreset[];
  /** Which part is showing to begin with: the list of choices, or the calendar with a time. Default "presets". */
  defaultView?: "presets" | "custom";
  /** Replaces the button. One element that takes a ref and props, such as a `Button`. */
  trigger?: ReactNode;
  /** Which edge of the button the panel lines up with. Default "start". */
  align?: "start" | "center" | "end";
  /** Whether the panel is open, when you control it. */
  open?: boolean;
  /** Whether the panel is open to begin with. */
  defaultOpen?: boolean;
  /** Called when the panel opens or closes: by the button, Escape, a click outside, or a choice. */
  onOpenChange?: (open: boolean) => void;
  /** The words the button and the panel say, for translation. */
  labels?: SnoozeLabels;
}

/**
 * Snooze until later, for email, tasks and notifications: four choices worked out from now (later today, tomorrow morning,
 * this weekend, next week) with the day and the time at the right of each, in the locale and the time zone you give. A choice
 * that would land in the past is left out. "Pick date and time" opens a calendar and a time field and writes the choice out in
 * words before it is made, and the zone is said in words at the foot. A choice snoozes at once, the result is announced ("Snoozed
 * until Thu 23 Oct, 08:00"), and every day is read in the zone against the `now` you pass, so the server and the browser agree.
 */
export function SnoozePopover({
  onSnooze,
  now,
  timeZone = "UTC",
  locale = "en-US",
  presets,
  defaultView,
  trigger,
  align = "start",
  open,
  defaultOpen = false,
  onOpenChange,
  labels,
  className,
  ...props
}: SnoozePopoverProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const [said, setSaid] = useState("");
  const content = useRef<HTMLDivElement>(null);
  const isOpen = open ?? ownOpen;
  // A panel that is open from the start (a preview, a first-run tip) never takes focus from the page: that is only for a panel somebody opened.
  const [wasOpen, setWasOpen] = useState(isOpen);
  const [fresh, setFresh] = useState(isOpen);
  if (isOpen !== wasOpen) {
    setWasOpen(isOpen);
    if (!isOpen) setFresh(false);
  }

  function setOpen(next: boolean) {
    // Cleared on the way in, so the same words are read out again after the next choice.
    if (next) setSaid("");
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  }

  return (
    <div data-slot="snooze-popover" className={cn("inline-flex max-w-full min-w-0", className)} {...props}>
      <Popover open={isOpen} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          {trigger ?? (
            <Button type="button" variant="outline" className="gap-2">
              <IconClock aria-hidden="true" />
              {words.trigger}
            </Button>
          )}
        </PopoverTrigger>
        <PopoverContent
          ref={content}
          align={align}
          collisionPadding={8}
          aria-label={words.title}
          onOpenAutoFocus={(event) => {
            // Focus goes to the first choice, the one the arrow keys start from.
            event.preventDefault();
            if (fresh) return;
            const first = content.current?.querySelector<HTMLElement>('[data-row][tabindex="0"]') ?? content.current?.querySelector<HTMLElement>("[data-row]");
            (first ?? content.current)?.focus({ preventScroll: true });
          }}
          className="flex max-h-[min(38rem,var(--radix-popover-content-available-height))] w-[min(20rem,calc(100vw-1rem))] flex-col overflow-hidden p-0"
        >
          <SnoozePanel
            onSnooze={onSnooze}
            now={now}
            timeZone={timeZone}
            locale={locale}
            presets={presets}
            defaultView={defaultView}
            labels={labels}
            onDone={({ text }) => {
              setSaid(text);
              setOpen(false);
            }}
            className="min-h-0 flex-1"
          />
        </PopoverContent>
      </Popover>
      {/* The panel is gone when the words are said, so they are said from here, where the button is. */}
      <p role="status" aria-live="polite" className="sr-only">
        {said}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, useSyncExternalStore, type ComponentProps, type KeyboardEvent } from "react";

import { IconAlertCircle, IconCalendar, IconChevronLeft, IconChevronRight, IconClock, IconGlobe, IconSpinner } from "@rhs-ui/icons";
import {
  addDays,
  clockText,
  daySlots,
  DEFAULT_LABELS,
  defaultPresets,
  dayNumber,
  fill,
  isThenable,
  presetOptions,
  readClock,
  rowText,
  slotText,
  toTimestamp,
  wallOf,
  whenText,
  zonedTime,
  zoneName,
  type CivilDay,
  type SnoozeLabels,
  type SnoozePreset,
  type SnoozeTime,
} from "@rhs-ui/application/snooze-popover/snooze";
import { Button } from "@rhs-ui/primitives/button";
import { Calendar } from "@rhs-ui/primitives/calendar";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@rhs-ui/primitives/select";
import { cn } from "@/lib/utils";

export interface SnoozePanelProps extends Omit<ComponentProps<"div">, "children" | "onChange"> {
  /**
   * The moment the person chose. It may return a promise: the row shows progress while it runs, and when it rejects the panel stays
   * open with a message so the choice can be made again.
   */
  onSnooze: (date: Date) => void | Promise<void>;
  /** The moment every choice is worked out from, and the moment the past starts. Leave it out to use the browser's clock once the page is live; pass it for the same times in server HTML, in tests and in previews. */
  now?: SnoozeTime;
  /** The time zone the choices, the calendar and the time are read in, so the server and the browser agree. Default "UTC". */
  timeZone?: string;
  /** The language of the weekdays, the months and the way a time is written. Default "en-US". */
  locale?: string;
  /** Your own choices instead of the four defaults (later today, tomorrow morning, this weekend, next week). */
  presets?: readonly SnoozePreset[];
  /** Which part is showing to begin with: the list of choices, or the calendar with a time. Default "presets". */
  defaultView?: "presets" | "custom";
  /** Called once a choice was made and saved, with the moment and the sentence that was announced, so a popover around the panel can close. */
  onDone?: (result: { date: Date; text: string }) => void;
  /** The words the panel says, for translation. */
  labels?: SnoozeLabels;
}

const subscribeNever = (): (() => void) => () => undefined;

/**
 * The clock the choices are worked out from: `now` when it is given, otherwise the browser's, once the page is live and then once a
 * minute, so a choice that has passed leaves the list. Null while the server renders and while the browser hydrates, so both write
 * the same text; a panel that mounts after the page is live has the time at once.
 */
function useClock(now: SnoozeTime | undefined): number | null {
  const mounted = useSyncExternalStore(subscribeNever, () => true, () => false);
  const [tick, setTick] = useState(() => Date.now());
  const pinned = now !== undefined;
  useEffect(() => {
    if (pinned) return;
    const timer = window.setInterval(() => setTick(Date.now()), 60_000);
    return () => window.clearInterval(timer);
  }, [pinned]);
  if (pinned) {
    const at = toTimestamp(now);
    if (!Number.isNaN(at)) return at;
  }
  return mounted ? tick : null;
}

/** A calendar day as the plain date the Calendar draws: its own local midnight, so the day it shows is the day we mean. */
const floating = (day: CivilDay) => new Date(day.year, day.month - 1, day.day);

const SLOTS = daySlots(30);

interface CustomProps {
  now: number;
  timeZone: string;
  locale: string;
  words: Required<SnoozeLabels>;
  busy: boolean;
  failed: boolean;
  onBack: () => void;
  onConfirm: (date: Date) => void;
}

/** The calendar and the time field, with the choice written out in words before it is made. */
function CustomPicker({ now, timeZone, locale, words, busy, failed, onBack, onConfirm }: CustomProps) {
  const today = wallOf(now, timeZone);
  const [day, setDay] = useState<CivilDay>(() => addDays(today, 1));
  const [time, setTime] = useState("08:00");
  const clock = readClock(time) ?? { hour: 8, minute: 0 };
  const instant = zonedTime({ ...day, ...clock }, timeZone);
  const isToday = dayNumber(day) === dayNumber(today);
  // Today, the slots that have gone are marked taken, so a time that has passed cannot be picked.
  const passed = isToday ? SLOTS.filter((slot) => slot <= clockText(today)) : [];
  const past = instant.getTime() <= now;
  const timeId = useId();

  function pickDay(picked: Date) {
    const next = { year: picked.getFullYear(), month: picked.getMonth() + 1, day: picked.getDate() };
    setDay(next);
    // Moving to today with a time that has already gone takes the next slot that has not.
    if (dayNumber(next) === dayNumber(today) && SLOTS.filter((slot) => slot <= clockText(today)).includes(time)) {
      const later = SLOTS.find((slot) => slot > clockText(today));
      if (later) setTime(later);
    }
  }

  return (
    <>
      <div className="flex shrink-0 items-center gap-1 border-b border-border py-1.5 pr-4 pl-1.5">
        <Button type="button" variant="ghost" size="sm" onClick={onBack} className="text-muted-foreground hover:text-foreground">
          <IconChevronLeft />
          {words.back}
        </Button>
        <h2 className="text-sm font-semibold tracking-[-0.01em]">{words.pick}</h2>
      </div>
      <div
        className="relative min-h-0 flex-1 overflow-y-auto overscroll-contain"
        onKeyDown={(event) => {
          // Enter on a day picks it, and Enter on the button confirms; Ctrl or Command with Enter confirms from anywhere in here.
          if (event.key === "Enter" && (event.ctrlKey || event.metaKey) && !past && !busy) {
            event.preventDefault();
            onConfirm(instant);
          }
        }}
      >
        <div className="flex justify-center pt-1">
          <Calendar value={floating(day)} onValueChange={pickDay} min={floating(today)} locale={locale} />
        </div>
        <div className="grid gap-3 px-4 pt-1 pb-4">
          <div role="group" aria-labelledby={timeId} className="flex items-center justify-between gap-3">
            <span id={timeId} className="text-sm font-medium">
              {words.time}
            </span>
            <Select value={time} onValueChange={setTime}>
              <SelectTrigger size="sm" aria-labelledby={timeId} className="w-32 tabular-nums">
                <span className="flex min-w-0 items-center gap-2">
                  <IconClock aria-hidden="true" className="size-4 text-muted-foreground" />
                  <SelectValue />
                </span>
              </SelectTrigger>
              <SelectContent align="end" className="max-h-72 min-w-32">
                {SLOTS.map((slot) => (
                  <SelectItem key={slot} value={slot} disabled={passed.includes(slot)} className="py-1.5 tabular-nums">
                    {slotText(slot, locale)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="rounded-lg border border-border bg-muted/40 px-3 py-2.5">
            <p className="text-xs text-muted-foreground">{words.until}</p>
            <p className="text-sm font-medium tracking-[-0.01em] tabular-nums">{whenText(instant.getTime(), locale, timeZone)}</p>
          </div>
          {past ? <p className="text-xs text-muted-foreground">{words.past}</p> : null}
          {failed ? (
            <p role="alert" className="flex items-start gap-1.5 text-xs leading-snug font-medium text-[color:color-mix(in_oklch,var(--destructive),var(--foreground)_30%)]">
              <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              {words.failed}
            </p>
          ) : null}
          {/* Off and busy are said with aria-disabled and aria-busy, not disabled: a disabled button gives up focus, which would leave a keyboard on no control. */}
          <Button
            type="button"
            aria-disabled={past || busy || undefined}
            aria-busy={busy || undefined}
            onClick={() => {
              if (!past && !busy) onConfirm(instant);
            }}
            className={cn("w-full aria-disabled:cursor-not-allowed", past && !busy && "opacity-50", busy && "aria-disabled:cursor-progress")}
          >
            {busy ? <IconSpinner data-slot="button-spinner" /> : null}
            {words.confirm}
          </Button>
        </div>
      </div>
    </>
  );
}

/**
 * The inside of the snooze popover, on its own, for a sheet on a phone: a list of choices worked out from now in a zone (later
 * today, tomorrow morning, this weekend, next week) with the day and the time at the right of each, a row that opens a calendar
 * and a time field, and the zone said in words at the foot. A choice that would land in the past is left out. Enter on a choice
 * snoozes at once; the calendar view writes the choice out before it is made. Every day is read in `timeZone` against `now`.
 */
export function SnoozePanel({ onSnooze, now, timeZone = "UTC", locale = "en-US", presets, defaultView = "presets", onDone, labels, className, ...props }: SnoozePanelProps) {
  const words: Required<SnoozeLabels> = { ...DEFAULT_LABELS, ...labels };
  const clock = useClock(now);
  const [view, setView] = useState<"presets" | "custom">(defaultView);
  const [pending, setPending] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const [said, setSaid] = useState("");
  const [activeId, setActiveId] = useState<string | null>(null);
  const root = useRef<HTMLDivElement>(null);
  const busy = useRef(false);

  const options = clock === null ? [] : presetOptions(presets ?? defaultPresets(words), clock, timeZone);
  const current = options.some((option) => option.preset.id === activeId) ? activeId : (options[0]?.preset.id ?? null);

  async function choose(date: Date, id: string) {
    if (busy.current) return;
    setFailed(false);
    const text = fill(words.snoozed, { when: whenText(date.getTime(), locale, timeZone) });
    let outcome: void | Promise<void>;
    try {
      outcome = onSnooze(date);
    } catch {
      setFailed(true);
      return;
    }
    if (isThenable(outcome)) {
      busy.current = true;
      setPending(id);
      try {
        await outcome;
      } catch {
        setFailed(true);
        return;
      } finally {
        busy.current = false;
        setPending(null);
      }
    }
    setSaid(text);
    onDone?.({ date, text });
  }

  function move(event: KeyboardEvent<HTMLUListElement>) {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const list = [...event.currentTarget.querySelectorAll<HTMLElement>("[data-row]")];
    const at = list.findIndex((row) => row === document.activeElement);
    const next = event.key === "Home" ? 0 : event.key === "End" ? list.length - 1 : Math.min(list.length - 1, Math.max(0, at + (event.key === "ArrowDown" ? 1 : -1)));
    event.preventDefault();
    list[next]?.focus();
  }

  const zone = clock === null ? "" : fill(words.zone, { zone: zoneName(clock, locale, timeZone) });

  return (
    <div ref={root} data-slot="snooze-panel" data-view={view} aria-busy={pending !== null || undefined} className={cn("flex min-h-0 flex-col bg-popover text-popover-foreground", className)} {...props}>
      {view === "custom" && clock !== null ? (
        <CustomPicker
          now={clock}
          timeZone={timeZone}
          locale={locale}
          words={words}
          busy={pending !== null}
          failed={failed}
          onBack={() => {
            setFailed(false);
            setView("presets");
            // The calendar leaves, and with it the button that had focus: the row that opened it takes it back.
            window.requestAnimationFrame(() => root.current?.querySelector<HTMLElement>("[data-pick]")?.focus());
          }}
          onConfirm={(date) => void choose(date, "custom")}
        />
      ) : (
        <>
          <div className="shrink-0 border-b border-border px-4 py-2.5">
            <h2 className="text-sm font-semibold tracking-[-0.01em]">{words.title}</h2>
          </div>
          <ul onKeyDown={move} className="relative grid min-h-0 flex-1 gap-px overflow-y-auto overscroll-contain p-1.5">
            {options.map(({ preset, date }) => (
              <li key={preset.id}>
                <button
                  type="button"
                  data-row=""
                  tabIndex={preset.id === current ? 0 : -1}
                  aria-disabled={pending !== null || undefined}
                  onFocus={() => setActiveId(preset.id)}
                  onClick={() => void choose(date, preset.id)}
                  className="flex w-full items-center justify-between gap-4 rounded-md px-2.5 py-2.5 text-left outline-none transition-colors duration-150 hover:bg-muted/70 focus-visible:bg-muted/70 focus-visible:ring-[3px] focus-visible:ring-inset focus-visible:ring-ring/40 aria-disabled:cursor-progress motion-reduce:transition-none"
                >
                  <span className="text-sm font-medium tracking-[-0.01em]">{preset.label}</span>
                  <span className="flex items-center gap-2 text-[0.8125rem] text-muted-foreground tabular-nums">
                    {pending === preset.id ? <IconSpinner aria-hidden="true" className="size-3.5" /> : null}
                    {clock === null ? "" : rowText(date.getTime(), clock, locale, timeZone, words)}
                  </span>
                </button>
              </li>
            ))}
            <li className={cn(options.length > 0 && "mt-1 border-t border-border pt-1")}>
              <button
                type="button"
                data-row=""
                data-pick=""
                tabIndex={current === null ? 0 : -1}
                onFocus={() => setActiveId("pick")}
                onClick={() => {
                  setView("custom");
                  // The row leaves, and with it the focus: the calendar takes it, on the day it opens on.
                  window.requestAnimationFrame(() => root.current?.querySelector<HTMLElement>("[data-slot='calendar'] button[tabindex='0']")?.focus());
                }}
                className="flex w-full items-center justify-between gap-4 rounded-md px-2.5 py-2.5 text-left outline-none transition-colors duration-150 hover:bg-muted/70 focus-visible:bg-muted/70 focus-visible:ring-[3px] focus-visible:ring-inset focus-visible:ring-ring/40 motion-reduce:transition-none"
              >
                <span className="flex items-center gap-2.5 text-sm font-medium tracking-[-0.01em]">
                  <IconCalendar aria-hidden="true" className="size-4 text-muted-foreground" />
                  {words.pick}
                </span>
                <IconChevronRight aria-hidden="true" className="size-4 text-muted-foreground" />
              </button>
            </li>
          </ul>
          {failed ? (
            <p role="alert" className="flex shrink-0 items-start gap-1.5 px-4 pb-2 text-xs leading-snug font-medium text-[color:color-mix(in_oklch,var(--destructive),var(--foreground)_30%)]">
              <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              {words.failed}
            </p>
          ) : null}
        </>
      )}
      {zone ? (
        <div className="flex shrink-0 items-start gap-2 border-t border-border bg-muted/30 px-4 py-2.5 text-xs leading-snug text-muted-foreground">
          <IconGlobe aria-hidden="true" className="mt-px size-3.5 shrink-0" />
          {zone}
        </div>
      ) : null}
      {/* Kept in the page when empty: a live region that appears together with its message is often never read. */}
      <p role="status" aria-live="polite" className="sr-only">
        {pending !== null ? words.snoozing : said}
      </p>
    </div>
  );
}

/**
 * The date maths and the words behind SnoozePopover, as plain functions: they
 * hold no state, so a Server Component can use them too. Every calculation
 * takes the moment and the time zone as arguments and reads the calendar of
 * that zone through Intl, never the zone of the machine it runs on, so the
 * server and the browser reach the same dates, daylight saving included.
 */

/** A moment: a Date, an ISO string or a timestamp in milliseconds. */
export type SnoozeTime = Date | string | number;

/** A day on the calendar, with no zone and no time. `month` runs from 1 to 12. */
export interface CivilDay {
  year: number;
  month: number;
  day: number;
}

/** What the wall clock and the calendar of a zone show at one moment. */
export interface WallTime extends CivilDay {
  /** 0 for Sunday up to 6 for Saturday. */
  weekday: number;
  hour: number;
  minute: number;
}

/** One choice in the list: a label, and a way to work out the moment it means from now. */
export interface SnoozePreset {
  /** A stable identity: "tomorrow". It is the key of the row. */
  id: string;
  /** What it is called: "Tomorrow morning". */
  label: string;
  /** The moment this choice means, counted from `now` in `timeZone`, or `null` when it does not apply today. A moment that is not in the future is left out of the list. `atTime` and `nextWeekday` below do the zone work. */
  resolve: (now: Date, timeZone: string) => Date | null | undefined;
}

/** The words the popover says, for translation. `{when}` and `{zone}` are filled in. */
export interface SnoozeLabels {
  /** The button's text. Default "Snooze". */
  trigger?: string;
  /** The title of the list. Default "Snooze until". */
  title?: string;
  /** The first of the default choices. Default "Later today". */
  laterToday?: string;
  /** The second. Default "Tomorrow morning". */
  tomorrowMorning?: string;
  /** The third. Default "This weekend". */
  thisWeekend?: string;
  /** The fourth. Default "Next week". */
  nextWeek?: string;
  /** The row that opens the calendar. Default "Pick date and time". */
  pick?: string;
  /** Goes back from the calendar to the list. Default "Back". */
  back?: string;
  /** The label of the time field. Default "Time". */
  time?: string;
  /** The small line over the choice written out in words. Default "Snooze until". */
  until?: string;
  /** The button under the calendar. Default "Snooze". */
  confirm?: string;
  /** The word for today in the time at the right of a row. Default "Today". */
  today?: string;
  /** The word for tomorrow. Default "Tomorrow". */
  tomorrow?: string;
  /** The line that says which zone every time is in. Default "All times are in {zone}". */
  zone?: string;
  /** Shown when the picked moment has already gone. Default "That time has already passed. Pick a later one." */
  past?: string;
  /** Said when it is done. Default "Snoozed until {when}". */
  snoozed?: string;
  /** Said while the choice is being saved. Default "Snoozing". */
  snoozing?: string;
  /** Shown and said when saving failed. Default "Could not snooze. Nothing was changed." */
  failed?: string;
}

export const DEFAULT_LABELS = {
  trigger: "Snooze",
  title: "Snooze until",
  laterToday: "Later today",
  tomorrowMorning: "Tomorrow morning",
  thisWeekend: "This weekend",
  nextWeek: "Next week",
  pick: "Pick date and time",
  back: "Back",
  time: "Time",
  until: "Snooze until",
  confirm: "Snooze",
  today: "Today",
  tomorrow: "Tomorrow",
  zone: "All times are in {zone}",
  past: "That time has already passed. Pick a later one.",
  snoozed: "Snoozed until {when}",
  snoozing: "Snoozing",
  failed: "Could not snooze. Nothing was changed.",
} satisfies Required<SnoozeLabels>;

/** Puts values into a template: `fill("Snoozed until {when}", { when })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? (values[key] ?? match) : match));
}

/** Whether a handler returned a promise, so a quick answer does not flash a busy state. */
export function isThenable(value: unknown): value is PromiseLike<unknown> {
  return typeof value === "object" && value !== null && typeof (value as { then?: unknown }).then === "function";
}

/** A moment as milliseconds, or NaN when it is not a date at all. */
export function toTimestamp(time: SnoozeTime): number {
  return new Date(time).getTime();
}

const MINUTE = 60_000;
const DAY = 86_400_000;
const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

const wallFormats = new Map<string, Intl.DateTimeFormat>();

function wallFormat(timeZone: string): Intl.DateTimeFormat {
  let found = wallFormats.get(timeZone);
  if (!found) {
    try {
      found = new Intl.DateTimeFormat("en-US", { timeZone, hourCycle: "h23", weekday: "short", year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "numeric", second: "numeric" });
    } catch {
      // An unknown zone is read as UTC: a typo must not take the page down.
      found = wallFormat("UTC");
    }
    wallFormats.set(timeZone, found);
  }
  return found;
}

/** What the wall clock and the calendar in a zone show at a moment. */
export function wallOf(at: number, timeZone: string): WallTime {
  const parts = wallFormat(timeZone).formatToParts(at);
  const get = (type: string) => parts.find((part) => part.type === type)?.value ?? "";
  const number = (type: string) => Number(get(type));
  return {
    year: number("year"),
    month: number("month"),
    day: number("day"),
    weekday: Math.max(0, WEEKDAYS.indexOf(get("weekday"))),
    hour: number("hour") % 24,
    minute: number("minute"),
  };
}

/** How far a zone's wall clock is ahead of UTC at a moment, in minutes. */
function offsetMinutes(at: number, timeZone: string): number {
  const wall = wallFormat(timeZone).formatToParts(at);
  const get = (type: string) => Number(wall.find((part) => part.type === type)?.value);
  return Math.round((Date.UTC(get("year"), get("month") - 1, get("day"), get("hour") % 24, get("minute"), get("second")) - Math.floor(at / 1000) * 1000) / MINUTE);
}

/** The moment a wall clock in a zone shows a given time: "08:00 on 23 October in Amsterdam". It is worked out for that date, so daylight saving counts. */
export function zonedTime(wall: CivilDay & { hour: number; minute: number }, timeZone: string): Date {
  const asUtc = Date.UTC(wall.year, wall.month - 1, wall.day, wall.hour, wall.minute);
  // The offset is read at the guess, then again at the corrected guess, which is right on both sides of a change of clocks.
  const first = asUtc - offsetMinutes(asUtc, timeZone) * MINUTE;
  return new Date(asUtc - offsetMinutes(first, timeZone) * MINUTE);
}

/** A calendar day some days away: the arithmetic is on dates, so a day with 23 or 25 hours still counts as one. */
export function addDays(day: CivilDay, days: number): CivilDay {
  const moved = new Date(Date.UTC(day.year, day.month - 1, day.day + days));
  return { year: moved.getUTCFullYear(), month: moved.getUTCMonth() + 1, day: moved.getUTCDate() };
}

/** The number of the day, for comparing calendar days. */
export function dayNumber(day: CivilDay): number {
  return Math.floor(Date.UTC(day.year, day.month - 1, day.day) / DAY);
}

/** "08:00" for the wall time of a zone: the form the time field takes. */
export function clockText(wall: Pick<WallTime, "hour" | "minute">): string {
  return `${String(wall.hour).padStart(2, "0")}:${String(wall.minute).padStart(2, "0")}`;
}

/** "08:00" as an hour and a minute, or null when it cannot be read. */
export function readClock(text: string): { hour: number; minute: number } | null {
  const match = /^(\d{1,2}):(\d{2})$/.exec(text.trim());
  return match ? { hour: Number(match[1]), minute: Number(match[2]) } : null;
}

/** The day `days` away from today in the zone, at that time: `atTime(now, zone, { days: 1, hour: 8 })` is tomorrow at eight. */
export function atTime(now: Date, timeZone: string, when: { days?: number; hour?: number; minute?: number }): Date {
  const day = addDays(wallOf(now.getTime(), timeZone), when.days ?? 0);
  return zonedTime({ ...day, hour: when.hour ?? 9, minute: when.minute ?? 0 }, timeZone);
}

/**
 * The next time a weekday comes round in the zone (0 is Sunday): today when it is that day and `includeToday` is on, otherwise the
 * next one, at the hour and minute given.
 */
export function nextWeekday(now: Date, timeZone: string, weekday: number, when: { hour?: number; minute?: number; includeToday?: boolean } = {}): Date {
  const today = wallOf(now.getTime(), timeZone);
  const ahead = (weekday - today.weekday + 7) % 7;
  return atTime(now, timeZone, { days: ahead === 0 && !when.includeToday ? 7 : ahead, hour: when.hour ?? 9, minute: when.minute ?? 0 });
}

/** The four choices every snooze menu has: later today at six, tomorrow at eight, Saturday at nine, and Monday at eight. */
export function defaultPresets(words: Pick<Required<SnoozeLabels>, "laterToday" | "tomorrowMorning" | "thisWeekend" | "nextWeek">): SnoozePreset[] {
  return [
    { id: "later-today", label: words.laterToday, resolve: (now, timeZone) => atTime(now, timeZone, { hour: 18 }) },
    { id: "tomorrow-morning", label: words.tomorrowMorning, resolve: (now, timeZone) => atTime(now, timeZone, { days: 1, hour: 8 }) },
    {
      id: "this-weekend",
      label: words.thisWeekend,
      // On a Sunday the weekend is already here, and the next one is "Next week" away.
      resolve: (now, timeZone) => (wallOf(now.getTime(), timeZone).weekday === 0 ? null : nextWeekday(now, timeZone, 6, { hour: 9, includeToday: true })),
    },
    { id: "next-week", label: words.nextWeek, resolve: (now, timeZone) => nextWeekday(now, timeZone, 1, { hour: 8 }) },
  ];
}

/** One choice with the moment it works out to. */
export interface SnoozeOption {
  preset: SnoozePreset;
  date: Date;
}

/** The choices that still make sense now: each one worked out from `now`, those that would land in the past left out, and two that land on the same minute shown once. */
export function presetOptions(presets: readonly SnoozePreset[], now: number, timeZone: string): SnoozeOption[] {
  const seen = new Set<number>();
  const options: SnoozeOption[] = [];
  for (const preset of presets) {
    let date: Date | null | undefined;
    try {
      date = preset.resolve(new Date(now), timeZone);
    } catch {
      date = null;
    }
    if (!date || Number.isNaN(date.getTime()) || date.getTime() <= now) continue;
    const minute = Math.floor(date.getTime() / MINUTE);
    if (seen.has(minute)) continue;
    seen.add(minute);
    options.push({ preset, date });
  }
  return options;
}

function format(locale: string, timeZone: string, options: Intl.DateTimeFormatOptions, at: number): string {
  let text: string;
  try {
    text = new Intl.DateTimeFormat(locale, { ...options, timeZone }).format(at);
  } catch {
    text = new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" }).format(at);
  }
  // Intl writes some spaces as narrow no-break spaces, and the version of its data decides which: a plain space looks the same and every engine agrees on it.
  return text.replace(/\s/g, " ");
}

/** The way the locale writes a time: 24 hours with two digits where it counts that way ("08:00"), otherwise 12 hours ("8:00 AM"). */
function clockOptions(locale: string): Intl.DateTimeFormatOptions {
  let cycle: string | undefined;
  try {
    cycle = new Intl.DateTimeFormat(locale, { hour: "numeric" }).resolvedOptions().hourCycle;
  } catch {
    cycle = "h12";
  }
  return cycle === "h23" || cycle === "h24" ? { hour: "2-digit", minute: "2-digit", hourCycle: "h23" } : { hour: "numeric", minute: "2-digit" };
}

/** The time of day in the zone, in the locale's way of writing it. */
export function timeText(at: number, locale: string, timeZone: string): string {
  return format(locale, timeZone, clockOptions(locale), at);
}

/** The whole moment in words, for the preview and the announcement: "Thu 23 Oct, 08:00". */
export function whenText(at: number, locale: string, timeZone: string): string {
  return format(locale, timeZone, { weekday: "short", day: "numeric", month: "short", ...clockOptions(locale) }, at);
}

/**
 * The moment as the right-hand side of a row: "Today, 18:00", "Tomorrow, 08:00", and further out the weekday and the date,
 * "Sat 24 Oct, 09:00". The days are the days of the zone, so "tomorrow" is the day after today there and not 24 hours on.
 */
export function rowText(at: number, now: number, locale: string, timeZone: string, words: Pick<Required<SnoozeLabels>, "today" | "tomorrow">): string {
  const apart = dayNumber(wallOf(at, timeZone)) - dayNumber(wallOf(now, timeZone));
  const time = timeText(at, locale, timeZone);
  if (apart === 0) return `${words.today}, ${time}`;
  if (apart === 1) return `${words.tomorrow}, ${time}`;
  return `${format(locale, timeZone, { weekday: "short", day: "numeric", month: "short" }, at)}, ${time}`;
}

/** The name of the zone in full words, as the locale has it: "Central European Standard Time". */
export function zoneName(at: number, locale: string, timeZone: string): string {
  const parts = (() => {
    try {
      return new Intl.DateTimeFormat(locale, { timeZone, timeZoneName: "long" }).formatToParts(at);
    } catch {
      return new Intl.DateTimeFormat("en-US", { timeZone: "UTC", timeZoneName: "long" }).formatToParts(at);
    }
  })();
  return parts.find((part) => part.type === "timeZoneName")?.value ?? timeZone;
}

/** A slot such as "08:00" written the way the locale writes a time of day: "08:00", or "8:00 AM". */
export function slotText(slot: string, locale: string): string {
  const clock = readClock(slot);
  return clock ? format(locale, "UTC", clockOptions(locale), Date.UTC(2000, 0, 1, clock.hour, clock.minute)) : slot;
}

/** Every slot of the day at a step, as "HH:MM": what the time field offers. */
export function daySlots(step: number): string[] {
  const slots: string[] = [];
  for (let minutes = 0; minutes < 24 * 60; minutes += step) slots.push(`${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`);
  return slots;
}
